import { useEffect, useRef } from 'react';

const ART = ['data:image/png;base64,','data:image/png;base64,','data:image/png;base64,','data:image/png;base64,'];
const SIZE = 768;
type Stroke = { x: number; y: number; dx: number; dy: number; time: number };

function distance(mask: Uint8Array, w: number, h: number) {
  const d = new Float32Array(w * h);
  for (let i = 0; i < d.length; i++) d[i] = mask[i] ? 10000 : 0;
  for (let y = 1; y < h - 1; y++) for (let x = 1; x < w - 1; x++) {
    const i = y * w + x;
    d[i] = Math.min(d[i], d[i - 1] + 1, d[i - w] + 1, d[i - w - 1] + 1.4142, d[i - w + 1] + 1.4142);
  }
  for (let y = h - 2; y > 0; y--) for (let x = w - 2; x > 0; x--) {
    const i = y * w + x;
    d[i] = Math.min(d[i], d[i + 1] + 1, d[i + w] + 1, d[i + w + 1] + 1.4142, d[i + w - 1] + 1.4142);
  }
  return d;
}

const VERT = `attribute vec2 p; varying vec2 uv; void main(){uv=p*.5+.5;gl_Position=vec4(p,0.,1.);}`;
const FRAG = `precision highp float;
varying vec2 uv;
uniform sampler2D shape;
uniform sampler2D artwork;
uniform vec2 resolution;
uniform vec4 strokes[16];
uniform float strength[16];

vec2 warped(vec2 p){
  for(int i=15;i>=0;i--){
    vec2 c=strokes[i].xy; vec2 v=strokes[i].zw*strength[i];
    vec2 near=p-c-v*.5;
    float fall=exp(-dot(near,near)/.012);
    p-=v*fall*.42;
  }
  return p;
}
float original(vec2 p){
  vec2 rg=texture2D(shape,p).rg;return (rg.r*65280.+rg.g*255.)/65535.;
}
float heightAt(vec2 p){
  float h=original(warped(p));
  for(int i=0;i<16;i++){
    vec2 c=strokes[i].xy,v=strokes[i].zw*strength[i];
    float len=length(v);
    if(len>.001){
      float t=clamp(dot(p-c,v)/dot(v,v),0.,1.);
      float d=length(p-c-v*t);
      float wet=max(original(c),max(original(c+vec2(0.,.04)),original(c-vec2(0.,.04))));
      wet=max(wet,max(original(c+v*.25),original(c+v*.5)));
      float contact=exp(-d*d/.0028)*smoothstep(.005,.07,len);
      // Spread the displaced material into a low, translucent film.
      // The stroke widens and thins; it does not spring back like a cushion.
      h*=1.-contact*.70;
      float film=exp(-d*d/(.0018+.003*t))*.21*min(1.,wet);
      film*=smoothstep(.005,.06,len)*(1.-.48*t);
      h=max(h,film);
    }
  }
  return h;
}
float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
void main(){
  vec2 p=vec2(uv.x,1.-uv.y);
  float aspect=resolution.x/resolution.y;
  // Fixed artwork plane fits both desktop and portrait without stretching.
  vec2 plane=(p-.5)*vec2(max(1.,aspect/1.65),max(1.,1.65/aspect))+.5;
  float h=heightAt(plane);
  vec3 bg=vec3(.70+.055*(1.-p.y)-.025*length(p-.5));
  float shade=(heightAt(plane-vec2(.004,.016))+heightAt(plane-vec2(.009,.019))+heightAt(plane-vec2(-.001,.020))+heightAt(plane-vec2(.004,.025)))*.25;
  bg*=1.-smoothstep(.0,.65,shade)*.065;
  if(h<.005){gl_FragColor=vec4(bg,1.);return;}
  float e=2.5/768.;
  vec2 grad=vec2(heightAt(plane+vec2(e,0.))-heightAt(plane-vec2(e,0.)),heightAt(plane+vec2(0.,e))-heightAt(plane-vec2(0.,e)))/(2.*e);
  vec3 n=normalize(vec3(-grad*.027,1.));
  vec3 light=normalize(vec3(-.55,-.75,1.2));
  float diffuse=max(0.,dot(n,light));
  vec3 halfV=normalize(light+vec3(0.,0.,1.));
  float rim=pow(1.-n.z,1.3);
  float alpha=smoothstep(.004,.06,h);
  vec3 col=bg*exp(-vec3(.025)*h);
  float fresnel=.035+.965*pow(1.-n.z,3.);
  // Reflected studio cards: narrow white highlights and a darker edge band.
  // No diffuse plastic shading or broad opaque pink fill.
  vec3 reflection=reflect(vec3(0.,0.,-1.),n);
  float card=exp(-pow((reflection.x+.38)/.105,4.))*smoothstep(.0,.3,-reflection.y);
  float top=exp(-pow((reflection.y+.62)/.065,2.))*smoothstep(-.75,-.15,reflection.x);
  float edge=1.-smoothstep(.18,.60,h);
  float dark=(rim*.65+exp(-pow((reflection.y-.36)/.23,2.))*.16)*edge;
  col*=1.-dark*smoothstep(.02,.12,h);
  col=mix(col,vec3(1.),clamp((card*.88+top*.73)*(.3+.7*edge)+fresnel*.23,0.,.95));
  vec2 q=warped(plane);
  vec4 art=texture2D(artwork,q);
  float luminance=dot(art.rgb,vec3(.2126,.7152,.0722));
  float silver=smoothstep(.08,.94,luminance);
  float remaining=clamp(h/max(.025,original(q)),0.,1.);
  // Preserve each supplied letter and its fine optical detail. Neutralize
  // iridescent color in the live material; thinning transmits the backdrop.
  col=mix(col,vec3(silver),art.a*.86*pow(remaining,.7));
  alpha=max(alpha,art.a*remaining);
  vec2 cell=floor(q*125.);vec2 f=fract(q*125.)-.5;
  float chance=hash(cell);
  vec2 centre=vec2(hash(cell+7.),hash(cell+23.))*.35-.175;
  float r=.10+hash(cell+49.)*.13;
  float len=length(f-centre);
  float bubble=(1.-smoothstep(.017,.043,abs(len-r)))*step(.985,chance)*smoothstep(.35,.65,h);
  col=mix(col,col*.83,bubble*.5);
  float glint=(1.-smoothstep(.018,.065,length(f-centre-vec2(-r*.5,-r*.6))))*step(.985,chance)*smoothstep(.35,.65,h);
  col+=glint*.30;
  gl_FragColor=vec4(mix(bg,col,alpha),1.);
}`;

export default function App(){
  const ref=useRef<HTMLCanvasElement>(null);
  const hint=useRef<HTMLDivElement>(null);
  useEffect(()=>{
    if(!ref.current)return;
    const canvas=ref.current;
    const gl=canvas.getContext('webgl',{alpha:false,antialias:true});
    if(!gl)return;
    let disposed=false,raf=0,down=false,last={x:0,y:0};
    const strokes:Stroke[]=[];
    const shader=(type:number,source:string)=>{const s=gl.createShader(type)!;gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s)||'Shader failed');return s;};
    const prog=gl.createProgram()!;
    const vs=shader(gl.VERTEX_SHADER,VERT),fs=shader(gl.FRAGMENT_SHADER,FRAG);
    gl.attachShader(prog,vs);gl.attachShader(prog,fs);gl.linkProgram(prog);
    if(!gl.getProgramParameter(prog,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(prog)||'Link failed');
    gl.useProgram(prog);
    const buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);
    const attr=gl.getAttribLocation(prog,'p');gl.enableVertexAttribArray(attr);gl.vertexAttribPointer(attr,2,gl.FLOAT,false,0,0);
    const tex=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,tex);
    gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
    const artTex=gl.createTexture();
    gl.activeTexture(gl.TEXTURE1);gl.bindTexture(gl.TEXTURE_2D,artTex);
    gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
    gl.uniform1i(gl.getUniformLocation(prog,'artwork'),1);
    gl.uniform1i(gl.getUniformLocation(prog,'shape'),0);
    const uRes=gl.getUniformLocation(prog,'resolution'),uStroke=gl.getUniformLocation(prog,'strokes[0]'),uStrength=gl.getUniformLocation(prog,'strength[0]');
    const values=new Float32Array(64),forces=new Float32Array(16);
    let loaded=false;
    const draw=(now:number)=>{
      raf=0;if(!loaded||disposed)return;
      const box=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,1.7);
      const w=Math.round(box.width*dpr),h=Math.round(box.height*dpr);
      if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}
      gl.viewport(0,0,w,h);gl.uniform2f(uRes,w,h);values.fill(0);forces.fill(0);
      let moving=false;
      strokes.forEach((s,i)=>{const age=(now-s.time)/1000;const k=.92+.08*Math.exp(-Math.max(0,age-.45)/2.8);values.set([s.x,s.y,s.dx,s.dy],i*4);forces[i]=k;if(age<8)moving=true;});
      gl.uniform4fv(uStroke,values);gl.uniform1fv(uStrength,forces);gl.drawArrays(gl.TRIANGLE_STRIP,0,4);
      canvas.dataset.ready='true';canvas.dataset.strokes=String(strokes.length);
      if(moving||down)raf=requestAnimationFrame(draw);
    };
    const kick=()=>{if(!raf)raf=requestAnimationFrame(draw);};
    Promise.all(ART.map(src=>new Promise<HTMLImageElement>((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=src;}))).then(images=>{
      if(disposed)return;
      const atlas=document.createElement('canvas');atlas.width=atlas.height=1536;
      const ac=atlas.getContext('2d')!;
      const proportions=images.map(img=>img.width/img.height);
      const gap=.035,total=proportions.reduce((a,b)=>a+b,0);
      const letterHeight=(.84-gap*3)/total;
      let left=.08;
      images.forEach((img,i)=>{
        const width=letterHeight*proportions[i],height=letterHeight*1.65;
        ac.drawImage(img,left*1536,(.5-height/2)*1536,width*1536,height*1536);
        left+=width+gap;
      });
      gl.activeTexture(gl.TEXTURE1);gl.bindTexture(gl.TEXTURE_2D,artTex);
      gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,atlas);
      const off=document.createElement('canvas');off.width=off.height=SIZE;
      const c=off.getContext('2d',{willReadFrequently:true})!;
      c.drawImage(atlas,0,0,SIZE,SIZE);
      const rgba=c.getImageData(0,0,SIZE,SIZE).data,mask=new Uint8Array(SIZE*SIZE);
      for(let i=0;i<mask.length;i++)mask[i]=rgba[i*4+3]>110?1:0;
      let d=distance(mask,SIZE,SIZE);const map=new Uint8Array(SIZE*SIZE*4);
      for(let pass=0;pass<18;pass++){const sm=new Float32Array(d.length);for(let y=1;y<SIZE-1;y++)for(let x=1;x<SIZE-1;x++){const i=y*SIZE+x;sm[i]=(d[i]*4+d[i-1]+d[i+1]+d[i-SIZE]+d[i+SIZE])/8;}d=sm;}
      // Smooth the actual height, including the medial ridges, before lighting.
      for(let i=0;i<d.length;i++)d[i]=1-Math.exp(-d[i]/12);
      for(let pass=0;pass<90;pass++){const sm=new Float32Array(d.length);for(let y=1;y<SIZE-1;y++)for(let x=1;x<SIZE-1;x++){const i=y*SIZE+x;sm[i]=(d[i]*4+d[i-1]+d[i+1]+d[i-SIZE]+d[i+SIZE])/8;}d=sm;}
      for(let i=0;i<d.length;i++){const z=Math.round(d[i]*65535);map[i*4]=z>>8;map[i*4+1]=z&255;map[i*4+3]=255;}
      gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,tex);
      gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,SIZE,SIZE,0,gl.RGBA,gl.UNSIGNED_BYTE,map);
      loaded=true;kick();
    }).catch(()=>{canvas.dataset.error='asset-load';});
    const point=(e:PointerEvent)=>{const b=canvas.getBoundingClientRect(),a=b.width/b.height;return{x:((e.clientX-b.left)/b.width-.5)*Math.max(1,a/1.65)+.5,y:((e.clientY-b.top)/b.height-.5)*Math.max(1,1.65/a)+.5};};
    const start=(e:PointerEvent)=>{down=true;last=point(e);canvas.setPointerCapture(e.pointerId);};
    const move=(e:PointerEvent)=>{
      if(!down)return;const p=point(e),dx=p.x-last.x,dy=p.y-last.y;
      if(Math.hypot(dx,dy)<.003)return;
      const previous=strokes[strokes.length-1];
      if(previous&&performance.now()-previous.time<240&&Math.hypot(last.x-previous.x-previous.dx,last.y-previous.y-previous.dy)<.12&&previous.dx*dx+previous.dy*dy>=0){previous.dx=Math.max(-.65,Math.min(.65,previous.dx+dx));previous.dy=Math.max(-.45,Math.min(.45,previous.dy+dy));previous.time=performance.now();}
      else {strokes.push({x:last.x,y:last.y,dx:dx*.85,dy:dy*.85,time:performance.now()});if(strokes.length>16)strokes.shift();}
      last=p;if(hint.current)hint.current.style.opacity='0';kick();
    };
    const end=()=>{down=false;kick();};
    canvas.addEventListener('pointerdown',start);canvas.addEventListener('pointermove',move);canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);
    const ro=new ResizeObserver(kick);ro.observe(canvas);
    return()=>{disposed=true;cancelAnimationFrame(raf);ro.disconnect();canvas.removeEventListener('pointerdown',start);canvas.removeEventListener('pointermove',move);canvas.removeEventListener('pointerup',end);canvas.removeEventListener('pointercancel',end);gl.deleteTexture(tex);gl.deleteTexture(artTex);gl.deleteBuffer(buffer);gl.deleteProgram(prog);gl.deleteShader(vs);gl.deleteShader(fs);};
  },[]);
  return <main style={{height:'100dvh',width:'100%',position:'relative',background:'#b8b8b8',overflow:'hidden'}}>
    <canvas ref={ref} role="img" aria-label="Drag across WIPE to spread the clear liquid letters" style={{display:'block',width:'100%',height:'100%',touchAction:'none',cursor:'grab'}}/>
    <style>{`
      .wipe-gesture{position:absolute;left:50%;top:64%;width:210px;max-width:55%;transform:translateX(-50%);pointer-events:none;opacity:.55;transition:opacity .5s;text-align:center;color:#363636;font:11px Arial,sans-serif;letter-spacing:.08em}
      .wipe-gesture svg{display:block;width:100%;height:auto;overflow:visible}
      .wipe-gesture-dot{animation:wipe-demonstration 2.7s ease-in-out infinite;transform:translate(24px,44px)}
      @keyframes wipe-demonstration{0%,12%{transform:translate(24px,44px);opacity:0}22%{opacity:1}75%{transform:translate(216px,28px);opacity:1}88%,100%{transform:translate(216px,28px);opacity:0}}
      @media(prefers-reduced-motion:reduce){.wipe-gesture-dot{animation:none;transform:translate(120px,36px)}.wipe-gesture{transition:none}}
    `}</style>
    <div ref={hint} className="wipe-gesture" aria-hidden="true">
      <svg viewBox="0 0 240 72" fill="none">
        <path d="M24 44 C80 22 157 50 216 28" stroke="white" strokeWidth="2" strokeLinecap="round" strokeDasharray="3 6"/>
        <path d="M204 21 L218 27 L211 40" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
        <circle className="wipe-gesture-dot" r="11" fill="white" fillOpacity=".40" stroke="white" strokeWidth="1.5"/>
      </svg>
      <span>Press &amp; drag to wipe</span>
    </div>
  </main>;
}
